// BullMQ (Redis): producer with retries, a worker with concurrency, idempotent handler, DLQ-like failed set
import { Queue, Worker } from "bullmq";
const connection = { host: "localhost", port: 6379 };

export const emails = new Queue("emails", { connection, defaultJobOptions: {
  attempts: 5,
  backoff: { type: "exponential", delay: 2000 },       // 2s, 4s, 8s ...
  removeOnComplete: 1000,
  removeOnFail: false,                                   // keep failures for inspection / redrive
}});

// Producer: deterministic jobId = built-in dedupe (a second add with the same id is ignored)
await emails.add("order-confirmation", { orderId: "ord_9812" }, { jobId: "confirm:ord_9812" });

new Worker("emails", async (job) => {
  const { orderId } = job.data;
  const sent = await db.emailLog.insertIfAbsent({ key: `confirm:${orderId}` }); // unique constraint = idempotency
  if (!sent) return;                                                              // duplicate delivery -> no-op
  await mailer.send(await buildConfirmation(orderId));                            // may throw -> retry with backoff
}, { connection, concurrency: 10 });

// Transactional outbox: order + event in ONE transaction, then a relay publishes
await db.tx(async (t) => {
  const order = await t.orders.insert(input);
  await t.outbox.insert({ id: crypto.randomUUID(), type: "OrderPlaced", payload: { orderId: order.id }, sentAt: null });
});

// Relay (loop or cron): at-least-once publish, safe under concurrency with SKIP LOCKED
async function relay() {
  const batch = await db.query(
    "SELECT id, type, payload FROM outbox WHERE sent_at IS NULL ORDER BY created_at LIMIT 100 FOR UPDATE SKIP LOCKED",
  );
  for (const m of batch.rows) {
    await broker.publish(m.type, m.payload, { messageId: m.id }); // consumers dedupe by messageId
    await db.query("UPDATE outbox SET sent_at = now() WHERE id = $1", [m.id]);
  }
}

