// Vitest + supertest + Testcontainers: real Postgres, transaction-per-test isolation
import { PostgreSqlContainer } from "@testcontainers/postgresql";
import request from "supertest";
import { beforeAll, afterAll, beforeEach, afterEach, describe, it, expect } from "vitest";

let container, app, db;
beforeAll(async () => {
  container = await new PostgreSqlContainer("postgres:16").start();
  db = await connect(container.getConnectionUri());
  await migrate(db);
  app = buildApp({ orders: makeOrderService({ repo: makeRepo(db), payments: fakePayments(), clock: () => new Date("2026-10-05T10:00:00Z") }) });
}, 60_000);
afterAll(async () => { await db.end(); await container.stop(); });
beforeEach(() => db.query("BEGIN"));
afterEach(() => db.query("ROLLBACK"));     // every test starts from a clean slate

describe("orders", () => {
  it("rejects qty 0 with 422 and a field error", async () => {
    const res = await request(app).post("/v1/orders").send({ sku: "A-17", qty: 0 });
    expect(res.status).toBe(422);
    expect(res.body.errors[0].path).toContain("qty");
  });
});

# pytest + FastAPI TestClient with a fixture that rolls back the transaction
import pytest
from fastapi.testclient import TestClient

@pytest.fixture
def db(engine):
    conn = engine.connect(); tx = conn.begin()
    yield conn
    tx.rollback(); conn.close()           # isolation without truncating tables

def test_create_order_is_idempotent(db, client: TestClient):
    h = {"Idempotency-Key": "k1"}
    a = client.post("/v1/orders", json={"sku": "A-17", "qty": 2}, headers=h)
    b = client.post("/v1/orders", json={"sku": "A-17", "qty": 2}, headers=h)
    assert a.status_code == 201 and a.json()["id"] == b.json()["id"]

// Concrete defences in a Node/Express backend
import helmet from "helmet";
import { execFile } from "node:child_process";
import path from "node:path";
import dns from "node:dns/promises";
import net from "node:net";

app.use(helmet());                                  // sane security headers (HSTS, nosniff, frame options...)
app.use(express.json({ limit: "100kb" }));

// 1) Parameterised SQL: data never becomes code
const user = await pool.query("SELECT id FROM users WHERE email = $1", [email]);

// 2) No shell: arguments are passed as an array
execFile("convert", [inputPath, "-resize", "200x200", outPath], cb);

// 3) Path traversal guard
const BASE = path.resolve("/srv/uploads");
export function safePath(name: string) {
  const p = path.resolve(BASE, name);
  if (!p.startsWith(BASE + path.sep)) throw new Error("bad path");
  return p;
}

// 4) SSRF guard: resolve first, reject private ranges, then connect to the VALIDATED address
const isPrivate = (ip: string) =>
  net.isIP(ip) === 4
    ? /^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|0\.)/.test(ip)
    : /^(::1|fc|fd|fe80)/i.test(ip);

export async function assertPublicUrl(raw: string) {
  const u = new URL(raw);
  if (u.protocol !== "https:") throw new Error("https only");
  const addrs = await dns.lookup(u.hostname, { all: true });
  if (addrs.some((a) => isPrivate(a.address))) throw new Error("blocked address");
  return addrs[0].address; // connect to this IP to avoid DNS rebinding
}

// OpenTelemetry + structured logs: every log line carries the trace id
import { trace } from "@opentelemetry/api";
import pino from "pino";

const log = pino({ base: { service: "orders-api", version: process.env.GIT_SHA } });

export function withTrace() {
  const span = trace.getActiveSpan();
  const ctx = span?.spanContext();
  return ctx ? { traceId: ctx.traceId, spanId: ctx.spanId } : {};
}

app.post("/v1/orders", async (req, res) => {
  const t = trace.getTracer("orders");
  await t.startActiveSpan("place-order", async (span) => {
    try {
      span.setAttribute("order.items", req.body.items?.length ?? 0);   // attributes, NOT secrets
      const order = await orders.place(req.body);
      log.info({ ...withTrace(), orderId: order.id }, "order placed");
      res.status(201).json(order);
    } catch (e) {
      span.recordException(e as Error);
      log.error({ ...withTrace(), err: e }, "order failed");
      throw e;
    } finally { span.end(); }
  });
});

// RED metrics with prom-client: a latency histogram labelled by route (low cardinality!) and status class
import client from "prom-client";
const latency = new client.Histogram({ name: "http_request_duration_seconds", help: "latency", labelNames: ["route", "status"], buckets: [0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5] });
app.use((req, res, next) => {
  const end = latency.startTimer();
  res.on("finish", () => end({ route: req.route?.path ?? "unmatched", status: String(res.statusCode) }));
  next();
});
